import {locateNeighborhood,nearestSensors,locationError} from './geolocation.mjs';
import {sensorSummary} from './sensor-summary.mjs';
const $=id=>document.getElementById(id);let evidence=null,map=null,fireLayer=null,locationMarker=null;let sensorLayer=null;let neighborhoodData=null,neighborhoodLayer=null;const history=[];let busy=false;let userPosition=null,locationRequest=0;
const fmt=t=>t?new Date(t).toLocaleString('pt-BR',{timeZone:'America/Manaus',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})+' (Manaus)':'não informado';
function mapInit(){if(!window.L){$('map').textContent='O mapa não carregou. As evidências e a conversa continuam disponíveis.';return;}map=L.map('map',{scrollWheelZoom:false}).setView([-3.07,-60.05],11);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:17,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);fireLayer=L.layerGroup().addTo(map);sensorLayer=L.layerGroup().addTo(map);}
function chart(air){const series=air?.series??[];if(!series.length){$('chart').innerHTML='';$('series-table').textContent='Sem série disponível.';return;}const top=Math.max(10,...series.map(p=>p.value))*1.15;const x=i=>40+i*530/Math.max(1,series.length-1),y=v=>145-v/top*120;let svg='';for(let i=0;i<=3;i++){const value=top*i/3;svg+=`<line x1="40" y1="${y(value)}" x2="580" y2="${y(value)}" stroke="#dce6df"/><text x="3" y="${y(value)+4}">${value.toFixed(0)}</text>`;}const now=Date.now();for(let i=1;i<series.length;i++)svg+=`<line x1="${x(i-1)}" y1="${y(series[i-1].value)}" x2="${x(i)}" y2="${y(series[i].value)}" stroke="${series[i].time>now?'#ae622f':'#187757'}" stroke-width="2.5" ${series[i].time>now?'stroke-dasharray="5 4"':''}/>`;series.forEach((p,i)=>{if(i%6===0)svg+=`<text x="${x(i)}" y="170" text-anchor="middle">${new Date(p.time).toLocaleTimeString('pt-BR',{timeZone:'America/Manaus',hour:'2-digit',minute:'2-digit'})}</text>`});$('chart').innerHTML=svg;const table=document.createElement('table');const header=table.insertRow();['Horário (Manaus)','PM2,5 (µg/m³)','Tipo'].forEach(t=>{const th=document.createElement('th');th.textContent=t;header.append(th)});for(const p of series){const row=table.insertRow();[fmt(p.time),p.value.toFixed(1),p.time>now?'Previsão':'Estimativa passada'].forEach(t=>row.insertCell().textContent=t)}$('series-table').replaceChildren(table);}
function render(){renderClassification();renderSensors();const {air,fire,errors,agent}=evidence;const warnings=[];if(evidence.history?.error)warnings.push(evidence.history.error);if(!air?.available)warnings.push('Estimativa do ar indisponível ou desatualizada.');if(!fire||fire.stale)warnings.push('Detecções de fogo indisponíveis ou desatualizadas.');if(Object.keys(errors??{}).length)warnings.push('Uma fonte falhou na última consulta; confira os horários.');$('status').classList.toggle('warning',warnings.length>0);$('status').textContent=warnings.length?warnings.join(' '):'Fontes consultadas automaticamente. Ar: sensores PurpleAir e estimativa regional CAMS. Focos: detecções por satélite.';$('past').textContent=air?.available?air.pastTrend:'Sem informação atual';$('future').textContent=air?.available?air.futureTrend:'Sem informação atual';$('agentStatus').textContent=agent.status==='unauthorized'?'IA indisponível · credencial recusada':agent.status==='connected'?'IA conectada · respostas com fontes':agent.configured?'IA configurada · conexão a verificar':'IA ainda não configurada';$('send').disabled=!agent.configured||busy;$('measurement').textContent=air?.current?`${air.stale?'Dado desatualizado. ':''}Estimativa de PM2,5: ${air.current.value.toFixed(1)} µg/m³, válida para ${fmt(air.current.time)}. Coletada em ${fmt(air.collectedAt)}. Horário de emissão do modelo não informado pela API.`:'Sem concentração disponível.';$('airTime').textContent=air?'Coletado em '+fmt(air.collectedAt):'Sem coleta válida';$('fireTime').textContent=fire?'Coletado em '+fmt(fire.collectedAt):'Sem coleta válida';$('updated').textContent=(evidence.collectionMode==='on_access'?'Atualização por acesso após: ':'Próxima consulta: ')+fmt(evidence.nextCollection);if(evidence.collectionNote)$('collectionNote').textContent=evidence.collectionNote;$('fireInfo').textContent=fire?`${fire.stale?'Dados desatualizados. ':''}${fire.points.length.toLocaleString('pt-BR')} detecções no Amazonas na janela de 24 h consultada. Última detecção nos arquivos: ${fmt(fire.latestDetection)}. Cobertura parcial do dia.${fire.missingDates.length?' Arquivo(s) ausente(s): '+fire.missingDates.join(', ')+'.':''}`:'INPE indisponível: não é possível contar detecções.';chart(air);if(map){fireLayer.clearLayers();if(fire&&!fire.stale)for(const p of fire.points){const popup=document.createElement('div');popup.textContent=`Detecção de fogo · ${p.municipality}. ${fmt(p.time)}. Satélite ${p.satellite}. Não confirma origem da fumaça em Manaus.`;L.circleMarker([p.lat,p.lon],{radius:4,weight:1,color:'#a3541c',fillColor:'#e39443',fillOpacity:.65}).bindPopup(popup).addTo(fireLayer);}if(locationMarker)map.removeLayer(locationMarker);const div=document.createElement('div');div.className='location-label';div.textContent=selectedName();const small=document.createElement('small');small.textContent=sensorSummary(evidence.purpleair?.sensors,$('place').value);const note=document.createElement('small');note.textContent='Leituras pontuais, não de toda a área.';div.append(note);div.append(small);locationMarker=L.marker(selectedCenter(),{icon:L.divIcon({html:div,iconSize:[260,100],iconAnchor:[130,100],className:''})}).addTo(map);const pop=document.createElement('div');pop.textContent='Resumo dos sensores cadastrados no local selecionado, não uma média nem uma classificação de toda a área. A estimativa CAMS é apresentada separadamente abaixo.';locationMarker.bindPopup(pop);}}
async function load(){try{const r=await fetch('/api/evidence');if(!r.ok)throw Error();evidence=await r.json();render();}catch{$('status').textContent='Não foi possível consultar o servidor. Nenhum dado foi substituído por valores de exemplo.';$('status').classList.add('warning');}}
function message(text,type){const el=document.createElement('article');el.className='message '+type;el.textContent=text;$('messages').append(el);$('messages').scrollTop=$('messages').scrollHeight;return el;}
async function ask(question){if(busy||!question.trim())return;busy=true;$('locate').disabled=true;$('place').disabled=true;$('placeSearch').disabled=true;$('send').disabled=true;message(question,'user');const pending=message('Consultando as evidências e preparando a resposta…','assistant');try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,history,locationId:$('place').value})});const data=await r.json();if(!r.ok)throw Error(data.error||'Falha na resposta.');pending.textContent=data.answer;const meta=document.createElement('small');meta.textContent=`IA: ${data.model} · Evidências consultadas em ${fmt(data.evidenceTime)}`;pending.append(meta);history.push({role:'user',content:question},{role:'assistant',content:data.answer});while(history.length>6)history.shift();$('agentStatus').textContent='IA respondeu · dados das fontes conectadas';}catch(e){pending.className='message error';pending.textContent=e.message;$('agentStatus').textContent='Falha na resposta · mapa continua disponível';}finally{busy=false;$('locate').disabled=false;$('place').disabled=false;$('placeSearch').disabled=false;$('send').disabled=!evidence?.agent.configured;$('messages').scrollTop=$('messages').scrollHeight;}}
$('chatForm').addEventListener('submit',e=>{e.preventDefault();const q=$('question').value.trim();if(!q||busy)return;$('question').value='';ask(q);});document.querySelectorAll('.suggestions button').forEach(b=>b.addEventListener('click',()=>ask(b.textContent)));$('question').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('chatForm').requestSubmit();}});$('place').addEventListener('change',()=>{locationRequest++;userPosition=null;$('locate').disabled=false;$('locationStatus').textContent='Bairro escolhido manualmente.';selectNeighborhood();});$('region').addEventListener('click',()=>{if(map)map.fitBounds([[-9.8,-73.9],[2.3,-56.0]]);});mapInit();initNeighborhoods().finally(load);setInterval(()=>{if(!document.hidden)load();},300000);

function selectedFeature(){return neighborhoodData?.features.find(f=>f.properties.NOME_BAIRR===$('place').value);}
function selectedName(){return $('place').value==='manaus'?'Manaus':$('place').selectedOptions[0]?.textContent||'Manaus';}
function selectedCenter(){const feature=selectedFeature();if(feature&&window.L){const center=L.geoJSON(feature).getBounds().getCenter();return [center.lat,center.lng];}return [-3.07,-60.05];}
function fillPlaces(){const selected=$('place').value||'manaus';const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const query=normalize($('placeSearch').value);const names=(neighborhoodData?.features??[]).map(f=>f.properties.NOME_BAIRR).sort((a,b)=>a.localeCompare(b,'pt-BR'));$('place').replaceChildren();const options=[['manaus','Manaus - visão metropolitana'],...names.map(n=>[n,n.toLocaleLowerCase('pt-BR').replace(/(^|\s)\S/g,c=>c.toLocaleUpperCase('pt-BR'))])];for(const [id,label]of options){if(id!==selected&&query&&!normalize(label).includes(query))continue;const option=document.createElement('option');option.value=id;option.textContent=label;$('place').append(option);}$('place').value=selected;}
function selectNeighborhood(){if(neighborhoodLayer&&map)map.removeLayer(neighborhoodLayer);const feature=selectedFeature();if(map&&feature){neighborhoodLayer=L.geoJSON(feature,{style:{color:'#285f88',weight:2,fillOpacity:0.05}}).addTo(map);map.fitBounds(neighborhoodLayer.getBounds(),{padding:[25,25],maxZoom:14});}else if(map)map.setView([-3.07,-60.05],10);history.length=0;$('messages').replaceChildren();message('Local selecionado: '+selectedName()+'. Consulte abaixo os sensores disponíveis. Cada leitura representa seu ponto de instalação; o CAMS é uma estimativa regional.','assistant');const first=document.querySelector('.suggestions button');first.textContent='Como está o ar em '+selectedName()+'?';if(evidence)render();}
async function initNeighborhoods(){try{const response=await fetch('/neighborhoods.json');if(!response.ok)throw Error();neighborhoodData=await response.json();fillPlaces();selectNeighborhood();}catch{message('Não foi possível carregar os bairros. A visão metropolitana de Manaus continua disponível.','error');}}
$('placeSearch').addEventListener('input',fillPlaces);

function renderSensors(){
 const data=evidence.purpleair;const all=data?.sensors??[];const selected=all.filter(s=>$('place').value==='manaus'||s.neighborhood===$('place').value);const fresh=selected.filter(s=>s.available);
 $('purpleTime').textContent=data?.collectedAt?'Coletado em '+fmt(data.collectedAt):'Sem coleta válida';
 $('sensorSummary').textContent=sensorSummary(all,$('place').value)+' Leituras pontuais, não de toda a área. '+(selected.length?`${fresh.length} de ${selected.length} sensores com leitura recente neste local.`:'Sem sensor cadastrado dentro do bairro selecionado nesta lista. Isso não significa ar limpo.')+(data?.error?' A última consulta falhou; confira os horários.':'')+(data?.clockWarning?' '+data.clockWarning:'')+' Próxima consulta PurpleAir: '+fmt(data?.nextCollection)+'.';
 $('sensorList').replaceChildren();if(!selected.length&&userPosition){const note=document.createElement('p');note.textContent='Sensores mais próximos da localização informada (distância aproximada em linha reta). Não representam a qualidade do ar do seu bairro:';$('sensorList').append(note);for(const s of nearestSensors(all,userPosition)){const row=document.createElement('p');row.textContent=s.name+' · '+(s.neighborhood||'Bairro não identificado')+' · '+s.distance.toFixed(1)+' km · '+(s.available&&s.classification?'Faixa indicativa: '+s.classification.label:'Sem classificação atual')+' · Último contato: '+fmt(s.lastSeen);$('sensorList').append(row);}}if(sensorLayer)sensorLayer.clearLayers();
 for(const s of all){const text=`${s.name} · ${s.neighborhood||'Bairro não identificado'}: ${s.status}. ${s.classification?"Faixa indicativa: "+s.classification.label+" (Jev). ":"Classificação indisponível. "}${s.pm25===null?'Sem concentração':s.pm25.toFixed(1)+' µg/m³ de PM2,5 (10 min, sem correção)'}. Último contato: ${fmt(s.lastSeen)}. Uma medição pontual, não de todo o bairro.`;if(selected.includes(s)){const row=document.createElement('p');row.textContent=text;$('sensorList').append(row);}if(sensorLayer){const popup=document.createElement('div');popup.textContent=text;const label=document.createElement('span');label.textContent=s.name+' · '+(s.classification?'Faixa '+s.classification.label:s.status);L.circleMarker([s.lat,s.lon],{radius:9,weight:2,color:'#374151',fillColor:s.classification?.color??'#9ca3af',fillOpacity:.95}).bindTooltip(label).bindPopup(popup).addTo(sensorLayer);}}
}

function renderClassification(){
 const c=evidence.classifier;const names={not_configured:'Aguardando chave TypeSafe no servidor',pending:'Classificando com Jev…',connected:'Jev conectado · faixas conferidas numericamente',partial:'Uma ou mais respostas Jev foram rejeitadas na conferência',error:'Classificação Jev indisponível',waiting:'Aguardando próxima classificação',no_data:'Sem dados atuais para classificar'};
 $('jevStatus').textContent=names[c?.status]??'Classificação indisponível';
 $('bandLegend').replaceChildren();for(const b of c?.bands??[]){const item=document.createElement('span');item.style.backgroundColor=b.color;item.style.color=['muito_ruim','pessima'].includes(b.id)?'#fff':'#15241c';item.textContent=b.label+' · '+b.range;$('bandLegend').append(item);}
 const air=evidence.air;const band=air?.classification;$('camsBand').textContent=band?'Estimativa regional do modelo CAMS (~45 km) · faixa indicativa '+band.label+' · '+air.current.value.toFixed(1)+' µg/m³ · estimativa horária válida para '+fmt(air.current.time):'CAMS regional · classificação indisponível';
}

$('locate').addEventListener('click',()=>{
 if(busy)return;
 const status=$('locationStatus');
 if(!navigator.geolocation){status.textContent='Seu navegador não oferece localização. Selecione o bairro manualmente.';return;}
 if(!neighborhoodData){status.textContent='Os limites dos bairros ainda não estão disponíveis. Tente novamente em instantes.';return;}
 const request=++locationRequest;$('locate').disabled=true;status.textContent='Aguardando permissão e localização do navegador…';
 navigator.geolocation.getCurrentPosition(position=>{
  if(request!==locationRequest)return;$('locate').disabled=busy;
  if(busy){status.textContent='Aguarde a resposta do agente e tente novamente.';return;}
  const point={lat:position.coords.latitude,lon:position.coords.longitude,accuracy:position.coords.accuracy};
  const result=locateNeighborhood(neighborhoodData,point);
  if(result.status!=='found'){userPosition=null;status.textContent=result.status==='outside'?'Não identificamos um bairro de Manaus nesta localização. A cobertura atual é dos bairros cadastrados; selecione manualmente.':result.status==='boundary'?'A localização está próxima de uma divisa de bairros. Selecione seu bairro manualmente.':'A localização está imprecisa. Selecione seu bairro manualmente ou tente novamente.';if(evidence)renderSensors();return;}
  userPosition=point;$('placeSearch').value='';fillPlaces();$('place').value=result.id;selectNeighborhood();
  status.textContent='Bairro identificado: '+selectedName()+'. Precisão informada: cerca de '+Math.round(point.accuracy)+' m. Confira e corrija a seleção se necessário.';
 },error=>{if(request!==locationRequest)return;$('locate').disabled=busy;status.textContent=locationError(error.code);},{enableHighAccuracy:true,timeout:15000,maximumAge:0});
});
